def minDifference(nums: List[int]) -> int:
    'You are given an array of integers nums. Some values in nums are missing and are denoted by -1.\nYou can choose a pair of positive integers (x, y) exactly once and replace each missing element with either x or y.\nYou need to minimize the maximum absolute difference between adjacent elements of nums after replacements.\nReturn the minimum possible difference.\n \nExample 1:\n\nInput: nums = [1,2,-1,10,8]\nOutput: 4\nExplanation:\nBy choosing the pair as (6, 7), nums can be changed to [1, 2, 6, 10, 8].\nThe absolute differences between adjacent elements are:\n\n|1 - 2| == 1\n|2 - 6| == 4\n|6 - 10| == 4\n|10 - 8| == 2\n\n\nExample 2:\n\nInput: nums = [-1,-1,-1]\nOutput: 0\nExplanation:\nBy choosing the pair as (4, 4), nums can be changed to [4, 4, 4].\n\nExample 3:\n\nInput: nums = [-1,10,-1,8]\nOutput: 1\nExplanation:\nBy choosing the pair as (11, 9), nums can be changed to [11, 10, 9, 8].\n\n \nConstraints:\n\n2 <= nums.length <= 10^5\nnums[i] is either -1 or in the range [1, 10^9].'
    return Solution().minDifference(*copy.deepcopy((nums,)))

